/**
 * @file pokedexCaptureUpdate.ts
 * Shared Pokédex metadata updates on capture / hatch / offline autocatch.
 */

import type { PokedexEntry } from '../types/game/state.js';

export type PokedexCaptureFlags = {
  isShiny: boolean;
  isShadow: boolean;
};

/** Increment capture counters and shiny/shadow flags on an existing Pokédex entry. */
export function applyPokedexCaptureEntry(
  entry: PokedexEntry,
  captured: PokedexCaptureFlags,
): void {
  entry.count = (entry.count ?? 0) + 1;
  if (captured.isShiny) {
    entry.shinyCount = (entry.shinyCount ?? 0) + 1;
    entry.hasShiny = true;
    entry.shinySeen = true;
    entry.shinyCaught = true;
  }
  if (captured.isShadow) {
    entry.shadowCount = (entry.shadowCount ?? 0) + 1;
    entry.hasShadow = true;
  }
}

export function createPokedexEntryFromCapture(
  captured: PokedexCaptureFlags & {
    name: string;
    type: string;
    rarity: string;
  },
): PokedexEntry {
  return {
    seen: true,
    caught: true,
    shinySeen: captured.isShiny,
    shinyCaught: captured.isShiny,
    discovered: true,
    count: 1,
    shinyCount: captured.isShiny ? 1 : 0,
    hasShiny: captured.isShiny,
    shadowCount: captured.isShadow ? 1 : 0,
    hasShadow: captured.isShadow,
    name: captured.name,
    type: captured.type,
    rarity: captured.rarity,
    firstDiscoveredAt: Date.now(),
  };
}

/** Reconcile legacy / drifted entries and roster-owned shinies into hasShiny. */
export function reconcilePokedexShinyFlags(
  pokedex: Record<string, PokedexEntry>,
  rosterCreatures: Array<{ name?: string; type?: string; rarity?: string; isShiny?: boolean; isShadow?: boolean }>,
): boolean {
  let changed = false;

  for (const entry of Object.values(pokedex)) {
    if (!entry || typeof entry !== 'object') continue;
    const shinyCount = Number(entry.shinyCount);
    const legacyCaught = entry.shinyCaught === true;
    if ((Number.isFinite(shinyCount) && shinyCount > 0) || legacyCaught) {
      if (!entry.hasShiny) {
        entry.hasShiny = true;
        changed = true;
      }
      if (!entry.shinyCount || entry.shinyCount < 1) {
        entry.shinyCount = Math.max(1, Number.isFinite(shinyCount) ? shinyCount : 1);
        changed = true;
      }
    }
  }

  for (const creature of rosterCreatures) {
    if (!creature?.isShiny || !creature.name || !creature.type || !creature.rarity) continue;
    const key = `${creature.name}_${creature.type}_${creature.rarity}`;
    let entry = pokedex[key];
    if (!entry) {
      entry = createPokedexEntryFromCapture({
        name: creature.name,
        type: creature.type,
        rarity: creature.rarity,
        isShiny: true,
        isShadow: !!creature.isShadow,
      });
      pokedex[key] = entry;
      changed = true;
      continue;
    }
    if (!entry.hasShiny) {
      entry.hasShiny = true;
      changed = true;
    }
    const count = Number(entry.shinyCount);
    if (!Number.isFinite(count) || count < 1) {
      entry.shinyCount = 1;
      changed = true;
    }
    if (!entry.shinyCaught) {
      entry.shinyCaught = true;
      entry.shinySeen = true;
      changed = true;
    }
  }

  return changed;
}
