/**
 * Special vats: hidden until four proofs are met, then two incubators
 * (chromatic and shadow). The stored Pokémon is a template and comes back unchanged.
 */

import type { GameRuntime } from './src/types/game.js';
import type { CreatureData } from './src/types/creature.js';
import { Creature, CREATURE_IV_KEYS, rollCreatureIVs, type CreatureIvs } from './Creature.ts';
import { BALANCE } from './constants/balance/balance.ts';
import { POKEMON_SPRITE_IDS } from './constants/balance/dexAndCapture.ts';
import { DUST_CONVERSION_RATES } from './constants/balance/pokemartDust.ts';
import { POKEMON_SECONDARY_TYPES, RARITY } from './constants/core.ts';
import { logMessage } from './src/ui/modals.ts';
import { toast } from './toastManager.ts';
import { getShardKey } from './formatters.ts';
import { getVariantDustUpgradeLevel, VARIANT_DUST_UPGRADES } from './src/lib/variantDustUpgrades.ts';
import { publishResourcesChanged, publishShopChanged, publishStorageChanged } from './src/bus/publishHooks.js';
import { applyPokedexCaptureEntry, createPokedexEntryFromCapture } from './src/lib/pokedexCaptureUpdate.ts';
import { resolveCanonicalSpeciesName } from './src/lib/rosterSpeciesAliases.ts';
import { uiPokemonName, uiPokemonNameText } from './src/ui/i18n.ts';

export type SpecialVatId = 'chromatic' | 'shadow';

export interface SpecialIncubatorJob {
    creatureUid: string;
    dustSpent: number;
    /** Missing on legacy jobs paid in the vat's variant dust. */
    dustCurrency?: 'essenceDust';
    progress: number;
    catalystShardsSpent: number;
    activityMask?: number;
    /** Persisted so a ready experiment does not announce itself again after loading. */
    readyNotified?: boolean;
    dna?: { best: CreatureIvs; rerollsUsed: number };
}

const VATS = ['chromatic', 'shadow'] as const;
export const VAT_CATALYST_LIMIT = 50;
export const VAT_HATCH_PROGRESS = 100;
export const VAT_ACTIVITY_POINTS = { capture: 1, egg: 1, tower: 2 } as const;
type VatActivity = keyof typeof VAT_ACTIVITY_POINTS;
const VAT_ACTIVITY_FLAGS: Record<VatActivity, number> = { capture: 1, egg: 2, tower: 4 };
export const VAT_MASTERY_THRESHOLDS = [1, 4, 13, 40, 121] as const;
export const VAT_PREHEAT_UNLOCK_LEVEL = 1;
export const VAT_PROTOCOL_LEVEL = 2;
export const VAT_DNA_LEVEL = 3;
export const VAT_TRIPLE_PREHEAT_LEVEL = 4;
export const VAT_MEMORY_LEVEL = 5;
export const VAT_PROTOCOL_BONUS = 2;
export const VAT_DNA_REROLLS = 3;
export const VAT_MEMORY_PROGRESS_REDUCTION = 25;
const VAT_MEMORY_HATCH_PROGRESS = VAT_HATCH_PROGRESS * (1 - VAT_MEMORY_PROGRESS_REDUCTION / 100);
export const VAT_PREHEAT_SOURCE_LIMIT = 10;
export const VAT_PREHEAT_MAX = VAT_PREHEAT_SOURCE_LIMIT * Object.keys(VAT_ACTIVITY_POINTS).length;

export interface SpecialIncubatorPreheat {
    vat: SpecialVatId;
    creatureUid: string;
    contributions: Record<VatActivity, number>;
}

export function specialIncubatorPreheatProgress(preheat: SpecialIncubatorPreheat): number {
    const { capture, egg, tower } = preheat.contributions;
    return capture + egg + tower;
}

export interface SpecialIncubatorCatalyst {
    job: SpecialIncubatorJob;
    family: string;
    stock: number;
    isProtected: boolean;
    spent: number;
    max: number;
}

export interface SpecialIncubatorHintsSeen {
    rumor?: boolean;
    genetics: boolean;
    lieutenant: boolean;
    shadowFusion: boolean;
    shinyFusion: boolean;
}

export interface SpecialIncubatorState {
    unlocked: boolean;
    introShown: boolean;
    hintsSeen: SpecialIncubatorHintsSeen;
    legendaryShinyHatched?: boolean;
    completedExperiments: number;
    preheats: SpecialIncubatorPreheat[];
    mutatedFamilies: string[];
    chromatic: SpecialIncubatorJob | null;
    shadow: SpecialIncubatorJob | null;
}

export function specialIncubatorMasteryLevel(completed: number): number {
    const next = VAT_MASTERY_THRESHOLDS.findIndex((threshold) => (completed || 0) < threshold);
    return next === -1 ? VAT_MASTERY_THRESHOLDS.length : next;
}

export function specialIncubatorPreheatCapacity(level: number): number {
    if (level >= VAT_TRIPLE_PREHEAT_LEVEL) return 3;
    return level >= VAT_PREHEAT_UNLOCK_LEVEL ? 1 : 0;
}

export const SPECIAL_INCUBATOR_ESSENCE_DUST_MULT = 100;
export const SPECIAL_INCUBATOR_LIEUTENANT_TRUST = 3;

const HINT_ORDER: Array<{ key: keyof SpecialIncubatorHintsSeen; proof: 'genetics' | 'lieutenant' | 'shadowFusion' | 'shinyFusion'; i18n: string }> = [
    { key: 'genetics', proof: 'genetics', i18n: 'specialIncubators.hintGenetics' },
    { key: 'lieutenant', proof: 'lieutenant', i18n: 'specialIncubators.hintLieutenant' },
    { key: 'shadowFusion', proof: 'shadowFusion', i18n: 'specialIncubators.hintShadowFusion' },
    { key: 'shinyFusion', proof: 'shinyFusion', i18n: 'specialIncubators.hintShinyFusion' },
];

const INTRO_STEPS = [
    'specialIncubators.introCost',
    'specialIncubators.introActivity',
    'specialIncubators.introBirth',
] as const;

type NarrativeBind = {
    bindData?: (data: {
        speaker?: string;
        portrait?: 'chen' | 'rocketScientist';
        title?: string;
        text?: string;
        indicator?: string;
        boxClass?: string;
        actions?: Array<{ id?: string; text: string; class?: string }>;
        actionCallback?: (action: { id?: string }, index: string) => void;
    }) => void;
    closeOverlay?: () => void;
    escapeHtml?: (value: string) => string;
    overlay?: HTMLElement | null;
};

const LISTENERS_KEY = '__poketimeSpecialIncubatorListeners';

/** Vite can evaluate this module twice in dev (the Svelte file imports it with `?t=`). A module-local set would leave the open modal subscribed to the other copy, so cancel would clear the job and the button would stay. */
function specialIncubatorListeners(): Set<() => void> {
    const host = globalThis as typeof globalThis & { [LISTENERS_KEY]?: Set<() => void> };
    return host[LISTENERS_KEY] ?? (host[LISTENERS_KEY] = new Set());
}

export function subscribeSpecialIncubators(listener: () => void): () => void {
    const listeners = specialIncubatorListeners();
    listeners.add(listener);
    return () => listeners.delete(listener);
}

function notifySpecialIncubators(): void {
    specialIncubatorListeners().forEach((listener) => listener());
}

export function createDefaultSpecialIncubatorState(): SpecialIncubatorState {
    return {
        unlocked: false,
        introShown: false,
        hintsSeen: { rumor: false, genetics: false, lieutenant: false, shadowFusion: false, shinyFusion: false },
        legendaryShinyHatched: false,
        completedExperiments: 0,
        preheats: [],
        mutatedFamilies: [],
        chromatic: null,
        shadow: null,
    };
}

function normalizeVatPoints(value: unknown, limit: number): number {
    return typeof value === 'number' && Number.isFinite(value)
        ? Math.max(0, Math.min(limit, Math.floor(value)))
        : 0;
}

function normalizePreheat(raw: unknown): SpecialIncubatorPreheat | null {
    if (!raw || typeof raw !== 'object') return null;
    const { vat, creatureUid, contributions } = raw as Record<string, unknown>;
    if ((vat !== 'chromatic' && vat !== 'shadow') || typeof creatureUid !== 'string' || !creatureUid.trim()) return null;
    const points = contributions && typeof contributions === 'object' ? contributions as Record<string, unknown> : {};
    return {
        vat,
        creatureUid: creatureUid.trim(),
        contributions: {
            capture: normalizeVatPoints(points.capture, VAT_PREHEAT_SOURCE_LIMIT),
            egg: normalizeVatPoints(points.egg, VAT_PREHEAT_SOURCE_LIMIT),
            tower: normalizeVatPoints(points.tower, VAT_PREHEAT_SOURCE_LIMIT),
        },
    };
}

function normalizeJob(raw: unknown, now: number): SpecialIncubatorJob | null {
    if (!raw || typeof raw !== 'object') return null;
    const job = raw as Record<string, unknown>;
    const rawUid = job.creatureUid;
    const creatureUid = typeof rawUid === 'string' || typeof rawUid === 'number' ? String(rawUid).trim() : '';
    if (!creatureUid) return null;
    const endsAt = Number(job.endsAt);
    const catalystShardsSpent = normalizeVatPoints(Number(job.catalystShardsSpent), VAT_CATALYST_LIMIT);
    const legacyReady = job.progress === undefined && job.endsAt != null && Number.isFinite(endsAt) && endsAt <= now;
    const dustSpent = Number(job.dustSpent);
    const normalized: SpecialIncubatorJob = {
        creatureUid,
        dustSpent: Number.isFinite(dustSpent) ? Math.max(0, Math.min(Number.MAX_SAFE_INTEGER, dustSpent)) : 0,
        progress: legacyReady ? VAT_HATCH_PROGRESS : Math.max(catalystShardsSpent, normalizeVatPoints(job.progress, VAT_HATCH_PROGRESS)),
        catalystShardsSpent,
    };
    if (job.dustCurrency === 'essenceDust') normalized.dustCurrency = 'essenceDust';
    if (job.readyNotified === true) normalized.readyNotified = true;
    const activityMask = normalizeVatPoints(job.activityMask, 7);
    if (activityMask) normalized.activityMask = activityMask;
    if (normalized.progress >= VAT_MEMORY_HATCH_PROGRESS && job.dna && typeof job.dna === 'object') {
        const { best, rerollsUsed } = job.dna as Record<string, unknown>;
        if (best && typeof best === 'object') {
            const ivs = best as Record<string, unknown>;
            const valid = CREATURE_IV_KEYS.every((key) => typeof ivs[key] === 'number' && Number.isFinite(ivs[key]));
            if (valid) {
                normalized.dna = {
                    best: Object.fromEntries(CREATURE_IV_KEYS.map((key) => [key, normalizeVatPoints(ivs[key], 31)])) as CreatureIvs,
                    rerollsUsed: normalizeVatPoints(rerollsUsed, VAT_DNA_REROLLS),
                };
            }
        }
    }
    return normalized;
}

export function normalizeSpecialIncubatorState(raw: unknown, now = Date.now()): SpecialIncubatorState {
    const base = createDefaultSpecialIncubatorState();
    if (!raw || typeof raw !== 'object') return base;
    const source = raw as Record<string, unknown>;
    base.unlocked = source.unlocked === true;
    base.introShown = source.introShown === true;
    base.legendaryShinyHatched = source.legendaryShinyHatched === true;
    // Before mastery thresholds, every experiment increased geneticsLevel by one.
    base.completedExperiments = normalizeVatPoints(source.completedExperiments ?? source.geneticsLevel, Number.MAX_SAFE_INTEGER);
    if (Array.isArray(source.mutatedFamilies)) {
        const families = source.mutatedFamilies.filter((name): name is string => typeof name === 'string' && !!name.trim());
        base.mutatedFamilies = [...new Set(families.map((name) => getShardKey(name, null)))];
    }
    // The old clues described the quest-only gate; locked legacy saves get the new rumors.
    const hints = typeof source.legendaryShinyHatched === 'boolean' && source.hintsSeen && typeof source.hintsSeen === 'object'
        ? source.hintsSeen as Record<string, unknown>
        : {};
    base.hintsSeen = {
        rumor: hints.rumor === true,
        genetics: hints.genetics === true,
        lieutenant: hints.lieutenant === true,
        shadowFusion: hints.shadowFusion === true,
        shinyFusion: hints.shinyFusion === true,
    };
    base.chromatic = normalizeJob(source.chromatic, now);
    base.shadow = normalizeJob(source.shadow, now);
    const capacity = specialIncubatorPreheatCapacity(specialIncubatorMasteryLevel(base.completedExperiments));
    if (base.unlocked && capacity > 0) {
        const entries = Array.isArray(source.preheats) ? source.preheats : [source.preheat];
        const reserved = new Set([base.chromatic?.creatureUid, base.shadow?.creatureUid]);
        for (const rawEntry of entries) {
            const entry = normalizePreheat(rawEntry);
            if (!entry || reserved.has(entry.creatureUid)) continue;
            reserved.add(entry.creatureUid);
            base.preheats.push(entry);
            if (base.preheats.length >= capacity) break;
        }
    }
    return base;
}

export function ensureSpecialIncubatorState(game: GameRuntime): SpecialIncubatorState {
    const current = game.specialIncubatorState;
    if (!current || !current.hintsSeen || typeof current.completedExperiments !== 'number') {
        game.specialIncubatorState = normalizeSpecialIncubatorState(current);
    }
    return game.specialIncubatorState;
}

export interface SpecialIncubatorProofs {
    genetics: boolean;
    shinyFusion: boolean;
    shadowFusion: boolean;
    lieutenant: boolean;
}

export function readSpecialIncubatorProofs(game: GameRuntime): SpecialIncubatorProofs {
    const trust = Math.floor(Number(game.teamRocketState?.trustLevel) || 1);
    const spentVariantDust = (variant: 'shiny' | 'shadow') => VARIANT_DUST_UPGRADES.some((offer) =>
        offer.variant === variant && getVariantDustUpgradeLevel(game, offer.id) > 0,
    );
    return {
        genetics: game.specialIncubatorState?.legendaryShinyHatched === true,
        shinyFusion: (Number(game.shinyDust) || 0) > 0 || spentVariantDust('shiny'),
        shadowFusion: (Number(game.shadowDust) || 0) > 0 || spentVariantDust('shadow'),
        lieutenant: trust >= SPECIAL_INCUBATOR_LIEUTENANT_TRUST,
    };
}

export function specialIncubatorProofsMet(game: GameRuntime): boolean {
    const proofs = readSpecialIncubatorProofs(game);
    return proofs.genetics && proofs.shinyFusion && proofs.shadowFusion && proofs.lieutenant;
}

export function creatureHeldInSpecialIncubator(game: GameRuntime, creature: CreatureData | null | undefined): boolean {
    if (!creature?.uid) return false;
    const state = game.specialIncubatorState;
    if (!state) return false;
    const uid = String(creature.uid);
    return state.chromatic?.creatureUid === uid || state.shadow?.creatureUid === uid
        || state.preheats?.some((entry) => entry.creatureUid === uid) === true;
}

export function getSpecialIncubatorDustQuote(game: GameRuntime, template: CreatureData): { baseCost: number; cost: number } {
    const { rarity } = speciesRarity(game, template);
    const rates = DUST_CONVERSION_RATES as Record<string, number>;
    const rate = Math.max(0, Math.floor(Number(rates[rarity]) || rates[RARITY.COMMON] || 1));
    const baseCost = Math.max(1, Math.round(rate * SPECIAL_INCUBATOR_ESSENCE_DUST_MULT));
    return { baseCost, cost: baseCost };
}

export function getSpecialIncubatorProgressGoal(
    game: GameRuntime,
    template: Pick<CreatureData, 'name' | 'rarity'> | null | undefined,
): number {
    const state = game.specialIncubatorState;
    const remembered = template && state && specialIncubatorMasteryLevel(state.completedExperiments) >= VAT_MEMORY_LEVEL
        && state.mutatedFamilies?.includes(getShardKey(template.name, template.rarity));
    return remembered ? VAT_MEMORY_HATCH_PROGRESS : VAT_HATCH_PROGRESS;
}

export function getSpecialIncubatorReadyCount(game: GameRuntime): number {
    const state = game.specialIncubatorState;
    if (!state?.unlocked) return 0;
    return VATS.filter((vat) => {
        const job = state[vat];
        return job && job.progress >= getSpecialIncubatorProgressGoal(game, findCreatureByUid(game, job.creatureUid));
    }).length;
}

/** Offline hatches leave the announcement pending until catch-up finishes. */
export function notifySpecialIncubatorsReady(game: GameRuntime): void {
    const state = game.specialIncubatorState;
    if (!state?.unlocked || game.isOfflineSimulating) return;
    let notified = false;
    for (const vat of VATS) {
        const job = state[vat];
        if (!job || job.readyNotified) continue;
        const template = findCreatureByUid(game, job.creatureUid);
        if (job.progress < getSpecialIncubatorProgressGoal(game, template)) continue;
        confirmVatToast(game, 'specialIncubators.toastReadyTitle', 'specialIncubators.toastReadyBody', {
            name: template ? uiPokemonNameText(game, template.name) : tr(game, 'specialIncubators.title'),
            variant: variantWord(game, vat),
        });
        state[vat] = { ...job, readyNotified: true };
        notified = true;
    }
    if (notified) saveSpecialIncubators(game, 'special_incubator_ready');
}

export function getSpecialIncubatorTowerFloor(species: string): number | null {
    const target = resolveCanonicalSpeciesName(species);
    const ids = POKEMON_SPRITE_IDS as Record<string, number>;
    const id = ids[target];
    if (id === undefined || id < 1 || id > BALANCE.TOWER_ENEMY.DEX_ROTATION_MAX_ID) return null;
    const opponent = Object.keys(ids).find((name) => ids[name] === id);
    return opponent && resolveCanonicalSpeciesName(opponent) === target ? id : null;
}

function tr(game: GameRuntime, key: string, vars?: Record<string, unknown>): string {
    if (typeof game.t === 'function') return game.t(key, vars);
    return key;
}

function variantWord(game: GameRuntime, vat: SpecialVatId): string {
    const key = vat === 'chromatic'
        ? 'specialIncubators.variantWordChromatic'
        : 'specialIncubators.variantWordShadow';
    return tr(game, key);
}

function confirmVatToast(game: GameRuntime, titleKey: string, bodyKey: string, vars: Record<string, unknown>): void {
    if (typeof toast === 'undefined' || typeof toast.success !== 'function') return;
    toast.success(tr(game, titleKey), tr(game, bodyKey, vars));
}

function saveSpecialIncubators(game: GameRuntime, reason: string): void {
    game.saveGame?.({ reason });
}

function refundVatDust(game: GameRuntime, vat: SpecialVatId, job: SpecialIncubatorJob): void {
    const field = job.dustCurrency === 'essenceDust' ? 'essenceDust'
        : vat === 'chromatic' ? 'shinyDust' : 'shadowDust';
    game[field] = (Number(game[field]) || 0) + job.dustSpent;
}

function narrativeManager(): NarrativeBind | null {
    const host = globalThis as { narrativeManager?: NarrativeBind };
    return host.narrativeManager ?? null;
}

export function showSpecialIncubatorIntro(game: GameRuntime, automatic = true): void {
    const state = ensureSpecialIncubatorState(game);
    if (automatic && state.introShown) return;
    if (!state.unlocked) return;
    if (game.isOfflineSimulating) return;
    const nm = narrativeManager();
    if (!nm || typeof nm.bindData !== 'function' || typeof document === 'undefined') return;
    if (nm.overlay?.classList.contains('narrative-open')) return;
    const vars = {
        capture: VAT_ACTIVITY_POINTS.capture,
        egg: VAT_ACTIVITY_POINTS.egg,
        tower: VAT_ACTIVITY_POINTS.tower,
        catalystLimit: VAT_CATALYST_LIMIT,
    };
    const finish = (): void => {
        nm.closeOverlay?.();
        if (!state.introShown) {
            state.introShown = true;
            saveSpecialIncubators(game, 'special_incubator_intro');
        }
    };

    const showStep = (step: number): void => {
        const key = INTRO_STEPS[step];
        if (!key) return;
        const last = step >= INTRO_STEPS.length - 1;
        const rawText = tr(game, key, vars);
        const text = typeof nm.escapeHtml === 'function' ? nm.escapeHtml(rawText) : rawText;
        const title = typeof nm.escapeHtml === 'function'
            ? nm.escapeHtml(tr(game, `${key}Title`))
            : tr(game, `${key}Title`);
        const actions = [{
            id: last ? 'special-incubator-intro-done' : 'special-incubator-intro-next',
            text: tr(game, last ? 'specialIncubators.introDone' : 'specialIncubators.introNext'),
            class: 'narrative-continue-btn',
        }];
        if (step > 0) actions.push({
            id: 'special-incubator-intro-back', text: tr(game, 'specialIncubators.introBack'), class: 'narrative-next-btn',
        });
        actions.push({ id: 'special-incubator-intro-skip', text: tr(game, 'specialIncubators.introSkip'), class: 'narrative-next-btn' });
        nm.bindData?.({
            speaker: tr(game, 'specialIncubators.introSpeaker'),
            portrait: 'rocketScientist',
            title,
            text,
            indicator: tr(game, 'specialIncubators.introStep', { step: step + 1, total: INTRO_STEPS.length }),
            boxClass: 'narrative-game-modal narrative-story-quest narrative-lab-intro',
            actions,
            actionCallback: (action) => {
                if (action.id === 'special-incubator-intro-skip') finish();
                else if (action.id === 'special-incubator-intro-back') showStep(step - 1);
                else if (action.id === 'special-incubator-intro-next') showStep(step + 1);
                else if (action.id === 'special-incubator-intro-done') {
                    finish();
                    openSpecialIncubatorModalLogic(game);
                }
            },
        });
        nm.overlay?.classList.add('narrative-open');
        const dialogue = document.getElementById('narrativeDialogueBox');
        if (dialogue) dialogue.scrollTop = 0;
        document.getElementById(last ? 'special-incubator-intro-done' : 'special-incubator-intro-next')?.focus({ preventScroll: true });
    };

    try {
        showStep(0);
    } catch {
        /* The room stays open. Replay is available from the modal. */
    }
}

export function maybeUnlockSpecialIncubators(game: GameRuntime, options: { silent?: boolean } = {}): boolean {
    const state = ensureSpecialIncubatorState(game);
    if (state.unlocked) return false;
    if (!specialIncubatorProofsMet(game)) return false;
    state.unlocked = true;
    publishResourcesChanged();
    notifySpecialIncubators();
    saveSpecialIncubators(game, 'special_incubator_unlock');
    if (!options.silent && !game.isOfflineSimulating) showSpecialIncubatorIntro(game, true);
    return true;
}

export function maybeShowSpecialIncubatorHint(game: GameRuntime): void {
    const state = ensureSpecialIncubatorState(game);
    if (state.unlocked) return;
    const proofs = readSpecialIncubatorProofs(game);
    const any = proofs.genetics || proofs.shinyFusion || proofs.shadowFusion || proofs.lieutenant;
    if (!any) return;
    if (typeof game.showRivalToast !== 'function' || game.rivalState?.disabled) return;
    const hint = !state.hintsSeen.rumor
        ? { key: 'rumor' as const, i18n: 'specialIncubators.hintRumor' }
        : HINT_ORDER.find((entry) => !proofs[entry.proof] && !state.hintsSeen[entry.key]);
    if (!hint) return;
    game.showRivalToast(tr(game, hint.i18n));
    state.hintsSeen[hint.key] = true;
    saveSpecialIncubators(game, 'special_incubator_hint');
}

/** Unlock if the proofs just lined up. A Rocket gesture that only finishes the door does not also hint. */
export function onSpecialIncubatorRocketGesture(game: GameRuntime): void {
    if (maybeUnlockSpecialIncubators(game)) return;
    maybeShowSpecialIncubatorHint(game);
}

function findCreatureByUid(game: GameRuntime, uid: string): CreatureData | null {
    const lists = [game.storage, game.playerTeam, game.pension];
    for (const list of lists) {
        if (!Array.isArray(list)) continue;
        const found = list.find((creature) => creature && String(creature.uid) === uid);
        if (found) return found;
    }
    return null;
}

function findStoredCreatureByUid(game: GameRuntime, uid: string): CreatureData | undefined {
    return Array.isArray(game.storage) ? game.storage.find((creature) => String(creature?.uid) === uid) : undefined;
}

function clearVatFlag(creature: CreatureData | null): void {
    if (creature) delete creature.specialIncubatorVat;
}

function speciesRarity(game: GameRuntime, creature: CreatureData): { rarity: string; type: string } {
    const defined = typeof game.getPokemonBaseDefinition === 'function'
        ? game.getPokemonBaseDefinition(creature.name)
        : null;
    return {
        rarity: defined?.rarity || creature.rarity || RARITY.COMMON,
        type: defined?.type || creature.type || 'normal',
    };
}

function recordPokedex(game: GameRuntime, creature: CreatureData): void {
    if (!game.pokedex || typeof game.pokedex !== 'object') {
        game.pokedex = {};
    }
    const key = `${creature.name}_${creature.type}_${creature.rarity}`;
    const existing = game.pokedex[key]
        || Object.values(game.pokedex).find((entry) => entry
            && entry.name === creature.name
            && entry.type === creature.type
            && entry.rarity === creature.rarity);
    if (!existing) {
        game.pokedex[key] = createPokedexEntryFromCapture({
            name: creature.name,
            type: creature.type,
            rarity: creature.rarity,
            isShiny: !!creature.isShiny,
            isShadow: !!creature.isShadow,
        });
        if (typeof game.checkSpecialQuests === 'function') game.checkSpecialQuests('new_discovery');
        return;
    }
    applyPokedexCaptureEntry(existing, {
        isShiny: !!creature.isShiny,
        isShadow: !!creature.isShadow,
    });
}

function finishVat(game: GameRuntime, vat: SpecialVatId, job: SpecialIncubatorJob): CreatureData | null {
    const state = ensureSpecialIncubatorState(game);
    const template = findCreatureByUid(game, job.creatureUid);
    clearVatFlag(template);
    state[vat] = null;

    if (!template) {
        refundVatDust(game, vat, job);
        publishResourcesChanged();
        logMessage(tr(game, 'specialIncubators.logTemplateMissing'));
        notifySpecialIncubators();
        saveSpecialIncubators(game, 'special_incubator_refund');
        return null;
    }

    const species = speciesRarity(game, template);
    const isShiny = vat === 'chromatic';
    const isShadow = vat === 'shadow';
    const secondary = POKEMON_SECONDARY_TYPES[template.name] || null;
    const newborn = new Creature(
        template.name,
        species.type,
        1,
        species.rarity,
        false,
        isShiny,
        secondary,
        false,
        false,
        isShadow,
    );
    if (job.dna) Object.assign(newborn, job.dna.best);
    newborn.recalculateStats();
    newborn.heal();
    const born = newborn as unknown as CreatureData;

    const existing = typeof game.findCreatureByName === 'function'
        ? game.findCreatureByName(born.name, born.isShiny, born.isShadow)
        : null;
    const existingIsTemplate = !!existing && String(existing.uid) === String(template.uid);
    if (existingIsTemplate || (existing && typeof game.processFusion !== 'function')) {
        refundVatDust(game, vat, job);
        logMessage(tr(game, 'specialIncubators.logAlreadyVariant'));
        publishResourcesChanged();
        notifySpecialIncubators();
        saveSpecialIncubators(game, 'special_incubator_refund');
        return null;
    }
    let wasFusion = false;
    if (existing) {
        game.processFusion(born, existing);
        wasFusion = true;
    } else {
        if (!Array.isArray(game.storage)) game.storage = [];
        game.storage.push(born);
    }

    recordPokedex(game, born);
    if (!game.stats || typeof game.stats !== 'object') game.stats = {} as GameRuntime['stats'];
    if (born.isShiny) game.stats.shiniesObtained = (Number(game.stats.shiniesObtained) || 0) + 1;
    if (born.isShadow) game.stats.shadowiesObtained = (Number(game.stats.shadowiesObtained) || 0) + 1;
    if (typeof game.checkAchievements === 'function') {
        game.checkAchievements(born.isShiny ? 'shiniesObtained' : 'shadowiesObtained');
    }

    const previousLevel = specialIncubatorMasteryLevel(state.completedExperiments);
    state.completedExperiments = Math.min(Number.MAX_SAFE_INTEGER, state.completedExperiments + 1);
    const family = getShardKey(template.name, template.rarity);
    if (!state.mutatedFamilies.includes(family)) state.mutatedFamilies.push(family);
    const level = specialIncubatorMasteryLevel(state.completedExperiments);
    logMessage(tr(game, wasFusion ? 'specialIncubators.logBornFused' : 'specialIncubators.logBorn', { name: born.name }));
    if (level === VAT_PREHEAT_UNLOCK_LEVEL && previousLevel < level) {
        confirmVatToast(game, 'specialIncubators.preheatUnlockedTitle', 'specialIncubators.preheatUnlockedBody', {});
    } else if (level > previousLevel) {
        confirmVatToast(game, 'specialIncubators.geneticsLevel', 'specialIncubators.masteryUnlockedBody', { level });
    }
    // Genetic Memory can make the other vat ready as soon as mastery/family changes.
    notifySpecialIncubatorsReady(game);
    publishResourcesChanged();
    publishStorageChanged();
    notifySpecialIncubators();
    saveSpecialIncubators(game, 'special_incubator_birth');
    return born;
}

export function claimSpecialIncubator(game: GameRuntime, vat: SpecialVatId): boolean {
    const state = ensureSpecialIncubatorState(game);
    const job = state[vat];
    if (!job || job.progress < getSpecialIncubatorProgressGoal(game, findCreatureByUid(game, job.creatureUid))) return false;
    const born = finishVat(game, vat, job);
    if (!born) return false;
    if (typeof game.showEggHatchModal === 'function') {
        void game.showEggHatchModal(born, String(born.rarity || 'common'));
    }
    return true;
}

export function specialIncubatorIvTotal(ivs: CreatureIvs): number {
    return CREATURE_IV_KEYS.reduce((total, key) => total + ivs[key], 0);
}

export function specialIncubatorProtocolBonus(job: SpecialIncubatorJob, source: VatActivity): number {
    const seen = ((job.activityMask ?? 0) & VAT_ACTIVITY_FLAGS[source]) !== 0;
    return seen ? 0 : VAT_PROTOCOL_BONUS;
}

/** Reveal the original roll, then compare up to three new complete sets of IVs. */
export function analyzeSpecialIncubatorDna(game: GameRuntime, vat: SpecialVatId): boolean {
    const state = ensureSpecialIncubatorState(game);
    const job = state[vat];
    if (!state.unlocked || specialIncubatorMasteryLevel(state.completedExperiments) < VAT_DNA_LEVEL
        || !job || job.progress < getSpecialIncubatorProgressGoal(game, findCreatureByUid(game, job.creatureUid))
        || (job.dna && job.dna.rerollsUsed >= VAT_DNA_REROLLS)
        || !findCreatureByUid(game, job.creatureUid)) return false;

    const rolled = rollCreatureIVs();
    const previous = job.dna;
    const best = previous && specialIncubatorIvTotal(previous.best) >= specialIncubatorIvTotal(rolled)
        ? previous.best : rolled;
    state[vat] = { ...job, dna: { best, rerollsUsed: previous ? previous.rerollsUsed + 1 : 0 } };
    game.saveGame?.({ reason: 'special_incubator_dna', immediate: true });
    notifySpecialIncubators();
    return true;
}

export function restoreSpecialIncubatorsOnLoad(game: GameRuntime): void {
    const state = game.specialIncubatorState = normalizeSpecialIncubatorState(game.specialIncubatorState);
    for (const vat of VATS) {
        const job = state[vat];
        if (!job) continue;
        const template = findCreatureByUid(game, job.creatureUid);
        if (template) template.specialIncubatorVat = vat;
    }
    for (const preheat of state.preheats) {
        const template = findStoredCreatureByUid(game, preheat.creatureUid);
        if (template) template.specialIncubatorVat = preheat.vat;
    }
    if (!maybeUnlockSpecialIncubators(game)) {
        publishResourcesChanged();
        notifySpecialIncubators();
    }
}

export function catchUpSpecialIncubatorIntroOnLoad(game: GameRuntime): void {
    const state = ensureSpecialIncubatorState(game);
    notifySpecialIncubatorsReady(game);
    if (state.unlocked && !state.introShown) showSpecialIncubatorIntro(game, true);
}

/** A stored Pokémon can enter this vat when it exists, is not already incubating, and is not already this variant. */
export function specialIncubatorTemplateEligible(
    game: GameRuntime,
    vat: SpecialVatId,
    creature: CreatureData | null | undefined,
): boolean {
    if (!creature?.uid || !creature.name) return false;
    if (creatureHeldInSpecialIncubator(game, creature)) return false;
    return !isAlreadyVatVariant(vat, creature);
}

function isAlreadyVatVariant(vat: SpecialVatId, creature: CreatureData): boolean {
    return vat === 'chromatic' ? !!creature.isShiny : !!creature.isShadow;
}

export function startSpecialIncubator(game: GameRuntime, vat: SpecialVatId, storageIndex: number): boolean {
    const state = ensureSpecialIncubatorState(game);
    if (!state.unlocked || state[vat]) return false;
    if (!Array.isArray(game.storage) || storageIndex < 0 || storageIndex >= game.storage.length) return false;
    const template = game.storage[storageIndex];
    if (!template) return false;
    if (!specialIncubatorTemplateEligible(game, vat, template)) {
        const held = !!template.uid && creatureHeldInSpecialIncubator(game, template);
        if (template.uid && template.name && !held) {
            logMessage(tr(game, 'specialIncubators.logAlreadyVariant'));
        }
        return false;
    }

    return launchSpecialIncubator(game, state, vat, template);
}

function launchSpecialIncubator(
    game: GameRuntime,
    state: SpecialIncubatorState,
    vat: SpecialVatId,
    template: CreatureData,
    preheat: SpecialIncubatorPreheat | null = null,
): boolean {
    const { cost } = getSpecialIncubatorDustQuote(game, template);
    const balance = Number(game.essenceDust);
    if (!Number.isFinite(balance) || balance < cost) {
        logMessage(tr(game, 'specialIncubators.logNeedDust'));
        return false;
    }

    game.essenceDust = balance - cost;
    template.specialIncubatorVat = vat;
    state[vat] = {
        creatureUid: String(template.uid),
        dustSpent: cost,
        dustCurrency: 'essenceDust',
        progress: preheat ? specialIncubatorPreheatProgress(preheat) : 0,
        catalystShardsSpent: 0,
    };
    if (preheat) state.preheats = state.preheats.filter((entry) => entry !== preheat);
    logMessage(tr(game, 'specialIncubators.logStarted', { name: template.name }));
    confirmVatToast(game, 'specialIncubators.toastStartTitle', 'specialIncubators.toastStartBody', {
        name: template.name,
        variant: variantWord(game, vat),
    });
    publishResourcesChanged();
    notifySpecialIncubators();
    saveSpecialIncubators(game, 'special_incubator_start');
    return true;
}

export function queueSpecialIncubatorPreheat(game: GameRuntime, vat: SpecialVatId, uid: string): boolean {
    const state = ensureSpecialIncubatorState(game);
    const capacity = specialIncubatorPreheatCapacity(specialIncubatorMasteryLevel(state.completedExperiments));
    if (!state.unlocked || state.preheats.length >= capacity) return false;
    const template = findStoredCreatureByUid(game, uid);
    if (!template || !specialIncubatorTemplateEligible(game, vat, template)) return false;

    state.preheats = [...state.preheats, { vat, creatureUid: uid, contributions: { capture: 0, egg: 0, tower: 0 } }];
    template.specialIncubatorVat = vat;
    notifySpecialIncubators();
    saveSpecialIncubators(game, 'special_incubator_preheat');
    return true;
}

export function promoteSpecialIncubatorPreheat(game: GameRuntime, uid: string): boolean {
    const state = ensureSpecialIncubatorState(game);
    const preheat = state.preheats.find((entry) => entry.creatureUid === uid);
    if (!state.unlocked || !preheat || state[preheat.vat]) return false;
    const template = findStoredCreatureByUid(game, preheat.creatureUid);
    if (!template?.name) return false;
    if (isAlreadyVatVariant(preheat.vat, template)) {
        logMessage(tr(game, 'specialIncubators.logAlreadyVariant'));
        return false;
    }
    return launchSpecialIncubator(game, state, preheat.vat, template, preheat);
}

export function cancelSpecialIncubatorPreheat(game: GameRuntime, uid: string): boolean {
    const state = ensureSpecialIncubatorState(game);
    const preheat = state.preheats.find((entry) => entry.creatureUid === uid);
    if (!preheat) return false;
    clearVatFlag(findCreatureByUid(game, preheat.creatureUid));
    state.preheats = state.preheats.filter((entry) => entry !== preheat);
    notifySpecialIncubators();
    saveSpecialIncubators(game, 'special_incubator_preheat_cancel');
    return true;
}

export function getSpecialIncubatorCatalyst(
    game: GameRuntime,
    job: SpecialIncubatorJob,
): SpecialIncubatorCatalyst | null {
    const template = findCreatureByUid(game, job.creatureUid);
    if (!template?.name) return null;
    const goal = getSpecialIncubatorProgressGoal(game, template);
    if (job.progress >= goal) return null;

    const family = getShardKey(template.name, template.rarity);
    const balance = Number(game.shards?.[family]);
    const stock = Number.isFinite(balance) ? Math.max(0, Math.floor(balance)) : 0;
    const isProtected = Array.isArray(game.protectedShards) && game.protectedShards.includes(family);
    const spent = job.catalystShardsSpent;
    const max = isProtected ? 0 : Math.min(stock, VAT_CATALYST_LIMIT - spent, goal - job.progress);
    return { job, family, stock, isProtected, spent, max };
}

export function injectSpecialIncubatorCatalyst(
    game: GameRuntime,
    vat: SpecialVatId,
    preview: SpecialIncubatorCatalyst,
    quantity: number,
): boolean {
    const state = ensureSpecialIncubatorState(game);
    const job = state[vat];
    if (!state.unlocked || !job || job !== preview.job || !Number.isSafeInteger(quantity)
        || quantity < 1 || quantity > preview.max) return false;

    const current = getSpecialIncubatorCatalyst(game, job);
    if (!current || quantity > current.max || current.stock !== preview.stock
        || current.family !== preview.family) return false;

    game.shards[current.family] = current.stock - quantity;
    state[vat] = {
        ...job,
        progress: job.progress + quantity,
        catalystShardsSpent: current.spent + quantity,
    };
    notifySpecialIncubatorsReady(game);
    publishResourcesChanged();
    publishShopChanged();
    notifySpecialIncubators();
    saveSpecialIncubators(game, 'special_incubator_catalyst');
    return true;
}

/** Counts successful egg hatches, manual/Porygon captures, and live Tower victories. */
export function recordSpecialIncubatorActivity(
    game: GameRuntime,
    source: VatActivity,
    creature: Pick<CreatureData, 'name' | 'rarity'> & Partial<Pick<CreatureData, 'isShiny'>>,
    options: { silent?: boolean } = {},
): void {
    if (source === 'egg' && creature.isShiny && creature.rarity === RARITY.LEGENDARY) {
        const state = ensureSpecialIncubatorState(game);
        if (!state.legendaryShinyHatched) {
            state.legendaryShinyHatched = true;
            saveSpecialIncubators(game, 'special_incubator_hatch_proof');
            maybeUnlockSpecialIncubators(game, { silent: options.silent });
        }
    }
    if (!game.specialIncubatorState?.unlocked || (game.isOfflineSimulating && source !== 'egg')) return;
    if (source === 'tower' && typeof document !== 'undefined' && document.hidden) return;
    const state = ensureSpecialIncubatorState(game);
    if (!state.chromatic && !state.shadow && !state.preheats.length) return;

    const species = resolveCanonicalSpeciesName(creature.name);
    const family = getShardKey(species, creature.rarity);
    const protocolUnlocked = specialIncubatorMasteryLevel(state.completedExperiments) >= VAT_PROTOCOL_LEVEL;
    const shouldLog = !options.silent && !game.isOfflineSimulating;
    const matches = (template: CreatureData | null | undefined): boolean => {
        if (!template) return false;
        return source === 'tower'
            ? resolveCanonicalSpeciesName(template.name) === species
            : getShardKey(template.name, template.rarity) === family;
    };
    let changed = false;
    for (const vat of VATS) {
        const job = state[vat];
        if (!job || job.progress >= VAT_HATCH_PROGRESS) continue;
        const template = findCreatureByUid(game, job.creatureUid);
        const goal = getSpecialIncubatorProgressGoal(game, template);
        if (job.progress >= goal || !matches(template)) continue;

        const bonus = protocolUnlocked ? specialIncubatorProtocolBonus(job, source) : 0;
        const gain = Math.min(VAT_ACTIVITY_POINTS[source] + bonus, goal - job.progress);
        const activityMask = (job.activityMask ?? 0) | VAT_ACTIVITY_FLAGS[source];
        state[vat] = { ...job, progress: job.progress + gain, activityMask };
        changed = true;
        if (shouldLog) {
            logMessage(tr(game, `specialIncubators.activityLog_${source}`, {
                gain,
                name: uiPokemonName(game, species),
                variant: variantWord(game, vat),
            }));
        }
    }
    let preheatsChanged = false;
    const preheats = state.preheats.map((preheat) => {
        if (preheat.contributions[source] >= VAT_PREHEAT_SOURCE_LIMIT) return preheat;
        const template = findStoredCreatureByUid(game, preheat.creatureUid);
        if (!template || !matches(template)) return preheat;
        const gain = Math.min(VAT_ACTIVITY_POINTS[source], VAT_PREHEAT_SOURCE_LIMIT - preheat.contributions[source]);
        if (shouldLog) logMessage(tr(game, 'specialIncubators.preheatLog', { gain, name: uiPokemonName(game, template.name) }));
        preheatsChanged = true;
        return { ...preheat, contributions: { ...preheat.contributions, [source]: preheat.contributions[source] + gain } };
    });
    if (preheatsChanged) state.preheats = preheats;
    if (!changed && !preheatsChanged) return;
    if (changed) notifySpecialIncubatorsReady(game);
    notifySpecialIncubators();
    saveSpecialIncubators(game, 'special_incubator_activity');
}

export function cancelSpecialIncubator(game: GameRuntime, vat: SpecialVatId): boolean {
    const state = ensureSpecialIncubatorState(game);
    const job = state[vat];
    if (!job) return false;
    const template = findCreatureByUid(game, job.creatureUid);
    if (job.progress >= getSpecialIncubatorProgressGoal(game, template)) return false;
    clearVatFlag(template);
    refundVatDust(game, vat, job);
    state[vat] = null;
    logMessage(tr(game, 'specialIncubators.logCancelled'));
    publishResourcesChanged();
    notifySpecialIncubators();
    saveSpecialIncubators(game, 'special_incubator_cancel');
    return true;
}

export function replaySpecialIncubatorIntro(game: GameRuntime): void {
    showSpecialIncubatorIntro(game, false);
}

export function openSpecialIncubatorModalLogic(game: GameRuntime): void {
    const state = ensureSpecialIncubatorState(game);
    if (!state.unlocked) return;
    void import('./src/lib/lazyModalMounts.ts').then(async ({ ensureLazyModalBeforeShowAsync }) => {
        const { publishModalOpened } = await import('./src/bus/publishHooks.js');
        await ensureLazyModalBeforeShowAsync('specialIncubatorModal');
        const modal = typeof document !== 'undefined' ? document.getElementById('specialIncubatorModal') : null;
        if (!modal) return;
        requestAnimationFrame(() => {
            modal.classList.add('show');
            publishModalOpened('specialIncubatorModal');
            notifySpecialIncubators();
            if (!state.introShown) showSpecialIncubatorIntro(game);
        });
    });
}

export function closeSpecialIncubatorModalLogic(): void {
    const modal = typeof document !== 'undefined' ? document.getElementById('specialIncubatorModal') : null;
    if (modal) modal.classList.remove('show');
    void import('./src/bus/publishHooks.js').then(({ publishModalClosed }) => {
        publishModalClosed('specialIncubatorModal');
    });
}

type GameCtor = { prototype: Record<string, unknown> };

export function applySpecialIncubatorSystem(GameClass: GameCtor): void {
    GameClass.prototype.openSpecialIncubatorModal = function (this: GameRuntime) {
        openSpecialIncubatorModalLogic(this);
    };
    GameClass.prototype.closeSpecialIncubatorModal = function (this: GameRuntime) {
        closeSpecialIncubatorModalLogic();
    };
    GameClass.prototype.startSpecialIncubator = function (this: GameRuntime, vat: SpecialVatId, storageIndex: number) {
        return startSpecialIncubator(this, vat, storageIndex);
    };
    GameClass.prototype.cancelSpecialIncubator = function (this: GameRuntime, vat: SpecialVatId) {
        return cancelSpecialIncubator(this, vat);
    };
    GameClass.prototype.claimSpecialIncubator = function (this: GameRuntime, vat: SpecialVatId) {
        return claimSpecialIncubator(this, vat);
    };
    GameClass.prototype.replaySpecialIncubatorIntro = function (this: GameRuntime) {
        replaySpecialIncubatorIntro(this);
    };
    GameClass.prototype.catchUpSpecialIncubatorIntroOnLoad = function (this: GameRuntime) {
        catchUpSpecialIncubatorIntroOnLoad(this);
    };
    GameClass.prototype.restoreSpecialIncubatorsOnLoad = function (this: GameRuntime) {
        restoreSpecialIncubatorsOnLoad(this);
    };
}
